import{_ as o,a0 as p,w as r,s as g,ao as l,I as e,a1 as t,A as i,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何修改 Linux 的 GRUB 啓動背景 | LCTT x X-CMD","titleTemplate":false,"description":"如何修改 Linux 的 GRUB 啓動背景 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何修改 Linux 的 GRUB 啓動背景 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何修改 Linux 的 GRUB 啓動背景 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170215 How to change the Linux Boot Splash screen","title":"如何修改 Linux 的 GRUB 啓動背景","tag":"201703","desc":""},"relativePath":"201703/20170215 How to change the Linux Boot Splash screen.md","filePath":"[post].md"}'),h={name:"201703/20170215 How to change the Linux Boot Splash screen.md"};function d(u,s,m,c,b,k){const a=p("Link");return r(),g("div",null,[s[20]||(s[20]=l('<h1 id="如何修改-linux-的-grub-啓動背景" tabindex="-1">如何修改 Linux 的 GRUB 啓動背景 <a class="header-anchor" href="#如何修改-linux-的-grub-啓動背景" aria-label="Permalink to “如何修改 Linux 的 GRUB 啓動背景”">​</a></h1><p><strong>何為 GRUB 背景（ Splash ）？</strong></p><p>GRUB 背景（ Splash ）只不過是一張圖像，在 Linux 系統啓動的時候顯示為背景。你可能知道 Grub (<strong>GR</strong>and <strong>U</strong>nified <strong>B</strong>ootloader 的簡寫) 是主流 Linux 發行版中廣泛使用的啓動裝載程序 (bootloader)。以 RedHat 為例，你會發現它在系統啓動之時顯示為空白或者是一個黑色背景。</p><p>GRUB 背景（ Splash ）的相關定義在 <code>grub.conf</code> 文件中，並且 splash 背景圖像應該存儲在 <code>/boot</code> 分區中。如果你覺得默認的空白屏相當無趣，同時又想按照自己的意願來修改它，那麼趕緊閲讀下方的每個步驟吧。</p><h3 id="開始前需要哪些準備工作" tabindex="-1">開始前需要哪些準備工作 <a class="header-anchor" href="#開始前需要哪些準備工作" aria-label="Permalink to “開始前需要哪些準備工作”">​</a></h3><ol><li>ImageMagick (僅在命令列中使用) 或者 GIMP (GUI 中使用)</li><li>一個樣例圖像</li></ol><h3 id="使用-gui-修改-grub-的-splash-背景" tabindex="-1">使用 GUI 修改 Grub 的 Splash 背景 <a class="header-anchor" href="#使用-gui-修改-grub-的-splash-背景" aria-label="Permalink to “使用 GUI 修改 Grub 的 Splash 背景”">​</a></h3><p>首先然我們來使用 GUI 來進行操作吧，這裏我們使用 GIMP 來作為圖像編輯器。</p><p><strong>步驟 1</strong>、 使用 GIMP 打開圖像 (路徑為：<em>應用 (Applications)</em> --&gt; <em>圖像 (Graphics)</em> --&gt; <em>GIMP 程序 (GNU Image Manipulation Program)</em>)</p><p><strong>步驟 2</strong>、 現在我們需要按實際情況將圖像縮放到 640x480 大小。為此，需要點擊 <em>圖像 (Image)</em> --&gt; <em>縮放圖像 (Scale Image)</em>。記住，要如下圖參數進行設置。修改寬度為 640，高度為 480。其他保持不變。</p>',10)),e("p",null,[t(a,{href:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/big/scale.JPG"},{default:i(()=>[...s[0]||(s[0]=[e("img",{src:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/scale.JPG",alt:"縮放 image"},null,-1)])]),_:1})]),s[21]||(s[21]=e("p",null,[n("點擊 "),e("strong",null,"縮放 (Scale)"),n(" 按鈕")],-1)),s[22]||(s[22]=e("p",null,[e("strong",null,"步驟 3"),n("、 然後，我們需要索引圖像，讓它僅使用 14 色。為此，點擊 "),e("em",null,"圖像 (Image)"),n(' --> 模式 (Mode) --> 索引 (Indexed)。點選 "生成最優調色板 (generate optimum palette)" 選項，並設置顏色最大值 (maximum number of colors) 為 14 (如下)。')],-1)),e("p",null,[t(a,{href:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/big/index.JPG"},{default:i(()=>[...s[1]||(s[1]=[e("img",{src:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/index.JPG",alt:"最優調色板限制為 14 色"},null,-1)])]),_:1})]),s[23]||(s[23]=e("p",null,[n("點擊 "),e("em",null,"轉換 (convert)"),n(" 按鈕")],-1)),s[24]||(s[24]=e("p",null,[e("strong",null,"步驟 4"),n('、 保存文件。這裏以文件名為 "UxTechno.xpm" 來保存。')],-1)),e("p",null,[t(a,{href:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/big/save.JPG"},{default:i(()=>[...s[2]||(s[2]=[e("img",{src:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/save.JPG",alt:"保存圖像文件"},null,-1)])]),_:1})]),s[25]||(s[25]=e("p",null,[e("strong",null,"步驟 5"),n('、 以 Zip 方式壓縮文件。為此，轉到文件的保存位置 --> 右擊並選擇 "壓縮 (Compress)" 選項，選擇 "gzip" 方法來壓縮。')],-1)),e("p",null,[t(a,{href:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/big/compress.JPG"},{default:i(()=>[...s[3]||(s[3]=[e("img",{src:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/compress.JPG",alt:""},null,-1)])]),_:1})]),s[26]||(s[26]=l(`<p><strong>步驟 6</strong>、 現在複製或移動 &quot;UxTechno.xpm.gz&quot; 到 <code>/boot/grub/UxTechno.xpm.gz</code>。</p><p><strong>步驟 7</strong>、 這一步，打開 <code>/boot/grub/grub.conf</code> 文件編輯 <code>splashimage</code> 參數如下，並保存文件。</p><p>最後，文件的內容應該是像這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grub.conf</span></span>
<span class="line"><span>generated by anaconda</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Note that you do not have to rerun grub after making changes to this file</span></span>
<span class="line"><span># NOTICE: You have a /boot partition. This means</span></span>
<span class="line"><span>    that # all kernel and initrd paths are relative to /boot/, eg. # root</span></span>
<span class="line"><span>    (hd0,0) # kernel /vmlinuz-version ro root=/dev/sda2 # initrd</span></span>
<span class="line"><span>    /initrd-[generic-]version.img #boot=/dev/sda default=0 timeout=5</span></span>
<span class="line"><span>    splashimage=(hd0,0)/grub/UxTechno.xpm.gz</span></span>
<span class="line"><span>    hiddenmenu   </span></span>
<span class="line"><span>    title Red Hat Enterprise Linux (2.6.32-220.el6.x86_64)</span></span>
<span class="line"><span>    root (hd0,0)</span></span>
<span class="line"><span>    kernel /vmlinuz-2.6.32-220.el6.x86_64 ro root=UUID=1d8c5075-1a5b-4fdc-ba15-0458b65c6012 rd_NO_LUKS rd_NO_LVM LANG=en_US.UTF-8 rd_NO_MD quiet SYSFONT=latarcyrheb-sun16 rhgb</span></span>
<span class="line"><span>    crashkernel=auto KEYBOARDTYPE=pc KEYTABLE=us rd_NO_DM initrd</span></span>
<span class="line"><span>    /initramfs-2.6.32-220.el6.x86_64.img</span></span></code></pre></div><p>當你重啓服務器之後，你講看到如下效果的 splash 背景圖像：</p>`,5)),e("p",null,[t(a,{href:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/big/Uxtecho_splash.JPG"},{default:i(()=>[...s[4]||(s[4]=[e("img",{src:"https://www.howtoforge.com/images/how_to_change_the_linux_splash_screen/Uxtecho_splash.JPG",alt:""},null,-1)])]),_:1})]),s[27]||(s[27]=l(`<h3 id="使用命令列修改-grub-的-splash-背景" tabindex="-1">使用命令列修改 Grub 的 Splash 背景 <a class="header-anchor" href="#使用命令列修改-grub-的-splash-背景" aria-label="Permalink to “使用命令列修改 Grub 的 Splash 背景”">​</a></h3><p>如果説你是命令列的超級粉絲，那就使用如下方法吧。</p><p><strong>步驟 1</strong>、 開始之前，我們需要修改圖像的像素分辨率。為此，我們還需要在 Linux 系統上安裝好 ImageMagick。在 CentOS / RHEL 上使用如下命令來進行交叉檢查。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># rpm -qa|grep -i ImageMagick</span></span></code></pre></div><p>如果命令沒有返回輸出 (即空白)，這意味這你的系統上還沒有安裝 ImageMagick。你必須運行下面的命令來安裝它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install ImageMagick</span></span></code></pre></div><p>安裝好了重新複核一下，你會得到類似如下的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># rpm -qa|grep -i ImageMagick</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ImageMagick-6.5.4.7-5.el6.x86_64</span></span></code></pre></div><p>然後，繼續接下來的配置。這裏我使用 UxTechno 的 logo 來做 splash 背景圖像。</p><p><strong>步驟 2</strong>、 使用如下命令來轉換像素深度。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># convert -depth 8 -colors 14 -resize 640x480 uxtechno_logo.jpg uxtechno_logo.xpm</span></span></code></pre></div><p>上述選項的意義如下：</p><ol><li>最大使用 14 色</li><li>分辨率為 640x480</li><li>使用 xpm 格式</li></ol><p><strong>步驟 3</strong>、 以 Zip 壓縮文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># gzip uxtechno_logo.xpm</span></span></code></pre></div><p><strong>步驟 4</strong>、 複製文件到 <code>/boot</code> 分區。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cp uxtechno_logo.xpm.gz /boot/grub/</span></span></code></pre></div><p><strong>步驟 5</strong>、 在 <code>/boot/grub/grub.conf</code> 文件中修改 <code>splashimage</code> 參數如下，並保存文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>splashimage=(hd0,0)/grub/uxtechno_logo.xpm</span></span></code></pre></div><p><strong>步驟 6</strong>、 最後，使用 <code>reboot</code> 命令重啓服務器。啓動界面將顯示使用 GUI 方式第 7 步中的圖像。</p><hr><p>譯者簡介：</p>`,22)),e("p",null,[t(a,{href:"http://GHLandy.com"},{default:i(()=>[...s[5]||(s[5]=[n("GHLandy",-1)])]),_:1}),s[6]||(s[6]=n(" —— 生活中所有歡樂與苦悶都應藏在心中，有些事兒註定無人知曉，自己也無從説起。",-1))]),s[28]||(s[28]=e("hr",null,null,-1)),e("p",null,[s[8]||(s[8]=n("via: ",-1)),t(a,{href:"https://www.howtoforge.com/tutorial/how-to-change-the-linux-splash-screen/"},{default:i(()=>[...s[7]||(s[7]=[n("https://www.howtoforge.com/tutorial/how-to-change-the-linux-splash-screen/",-1)])]),_:1})]),e("p",null,[s[12]||(s[12]=n("作者：",-1)),t(a,{href:"https://www.howtoforge.com/tutorial/how-to-change-the-linux-splash-screen/"},{default:i(()=>[...s[9]||(s[9]=[n("MANMOHAN MIRKAR",-1)])]),_:1}),s[13]||(s[13]=n(" 譯者：",-1)),t(a,{href:"https://github.com/GHLandy"},{default:i(()=>[...s[10]||(s[10]=[n("GHLandy",-1)])]),_:1}),s[14]||(s[14]=n(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[11]||(s[11]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[17]||(s[17]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[15]||(s[15]=[n("LCTT",-1)])]),_:1}),s[18]||(s[18]=n(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:i(()=>[...s[16]||(s[16]=[n("Linux中國",-1)])]),_:1}),s[19]||(s[19]=n(" 榮譽推出",-1))])])}const w=o(h,[["render",d]]);export{f as __pageData,w as default};
